<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\ValueObject\TemplateVersionContentTextVO;

trait TemplateVersionContentTextAttributeHolder
{
  protected TemplateVersionContentTextVO|string|null $contentText = null;
  protected bool $contentTextAssigned = false;

  public function getContentTextOrDefault(?TemplateVersionContentTextVO $contentText): ?TemplateVersionContentTextVO
  {
    return $this->contentTextAssigned ? ($this->contentText !== null ? TemplateVersionContentTextVO::from($this->contentText) : null) : $contentText;
  }
  public function contentText(TemplateVersionContentTextVO|string|null $contentText): static
  {
    $this->contentText = $contentText;
    $this->contentTextAssigned = true;
    return $this;
  }
  public function getContentText(): ?string
  {
    return $this->contentText instanceof TemplateVersionContentTextVO ? $this->contentText->value() : $this->contentText;
  }
  public function isContentTextAssigned(): bool
  {
    return $this->contentTextAssigned;
  }
  public function writeContentTextTo(mixed $att): void
  {
    if ($this->contentTextAssigned) {
      $att->contentText($this->contentText);
    }  }
  public function readContentTextFrom(mixed $att): void
  {
    if ($att->isContentTextAssigned() ) {
      $contentText = $att->getContentText();
      $this->contentText($contentText);
    }
  }
  public function unsetContentText(): static
  {
    $this->contentTextAssigned = false;
    return $this;
  }
  protected function withDefaultContentText(): void   
  {
  }
  protected function withAssertedContentTextRules(self $value, ConstraintFailList $errorsList): void  
  {
    if ($value->contentTextAssigned = $this->contentTextAssigned) {
      $value->contentText = TemplateVersionContentTextVO::tryFrom($this->contentText, $errorsList);
    }
  }
}
